import time

from pathlib import Path
from taf.sw.dcap.rd import rd

from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class DcapManager():
    _dcap_api = rd()
    basic_dcap_profiles = {"gnb_custom_profile": ["condor5gSyslog"],
                           "enb_custom_profile": ["condor4gSyslog"],
                           "bts_custom_profile": ["scf", "immediateSnapshot"]
                           }

    def __init__(self, node_id, node_mplane, dcap_host, vm_connection, dcap_port="9443", custom_profiles=None):
        self.node_id = node_id
        self.node_mplane = node_mplane
        self.dcap_alias = f"dcap_{self.node_id}"
        self.dcap_host = dcap_host
        self.dcap_port = dcap_port
        self.dcap_connection = self.connect_to_dcap_host(dcap_port, dcap_host, vm_connection)
        self.dcap_profiles = custom_profiles if custom_profiles else self.basic_dcap_profiles
        self.trace_id = None
        self.current_syslog = None
        self.bts_details = self._get_bts()

    def _is_dcap_controller_started(self, vm_connection):
        test_logger(f"{self.dcap_host, self.dcap_port} Checking DCAP Controller status")
        status = vm_connection.execute("DCAP_Basic_controller status")
        return True if "DCAP Basic health check passed" in str(status) else False

    def start_dcap_controller(self, vm_connection):
        test_logger(f"{self.dcap_host, self.dcap_port} DCAP_Basic_controller starting")
        start_status = vm_connection.execute("DCAP_Basic_controller start")
        if "All DCAP Basic containers started successfully" in str(start_status):
            test_logger(f"{self.dcap_host, self.dcap_port} All DCAP Basic containers started successfully. "
                        f"Waiting on health check pass.")
            end_time = time.time() + 60
            try:
                while time.time() < end_time:
                    status = vm_connection.execute("DCAP_Basic_controller status")
                    if "DCAP Basic health check passed" not in str(status):
                        time.sleep(5)
                    else:
                        test_logger(f"{self.dcap_host, self.dcap_port} DCAP Basic health check passed.")
                        break
            except TimeoutError as e:
                raise e
        else:
            test_logger(f"{self.dcap_host, self.dcap_port} DCAP Basic containers failed.", log_level="ERROR")
            raise Exception("Starting Dcap Failed!")  # TODO Implement Custom exception

    def check_and_start_dcap(self, vm_connection):
        if not self._is_dcap_controller_started(vm_connection):
            self.start_dcap_controller(vm_connection)
        else:
            test_logger(f"{self.dcap_host, self.dcap_port} DCAP Controller is already started")

    def connect_to_dcap_host(self, dcap_port, dcap_host, vm_connection):
        if vm_connection:
            self.check_and_start_dcap(vm_connection)
        test_logger(f"{self.dcap_host, self.dcap_port} Connecting to DCAP")
        return self._dcap_api.connect_to(host=dcap_host, port=dcap_port, alias=self.dcap_alias, secure=True)

    def _get_bts(self):
        btses = self._dcap_api.get_all_bts_info(connection=self.dcap_alias)
        bts_details = {"host":     self.node_mplane,
                       "username": "Nemuadmin",
                       "password": "nemuuser",
                       "port":     "443"}
        if not any(self.node_mplane == bts.get("host") for bts in btses):
            self._dcap_api.create_bts(**bts_details, bts_alias=f"dcap_{self.node_id}", connection=self.dcap_alias)

        return bts_details

    def start_trace(self):
        self.trace_id = self._dcap_api.start_trace(bts=self.bts_details, connection=self.dcap_alias,
                                                   wait_for_activation=True, **self.dcap_profiles).get("tracer_id")

    def stop_trace_and_download_logs(self, logs_dir):
        if self.is_trace_running():
            self.stop_trace()
            logs_dir = Path(logs_dir)
            if not logs_dir.exists():
                logs_dir.mkdir(parents=True)
            return self._dcap_api.get_results(result_id=self.trace_id,
                                              target_dir=logs_dir,
                                              connection=self.dcap_alias, timeout=600)
        test_logger("Trace already stopped")

    def stop_trace(self):
        self._dcap_api.stop_trace(self.trace_id, connection=self.dcap_alias)

    def is_trace_running(self):
        if self.trace_id:
            trace_info = self._dcap_api.get_trace_info_by_id(trace_id=self.trace_id,
                                                             connection=self.dcap_alias)
            if trace_info.get("status") == "running" and trace_info.get("status_details") == "":
                return True
        return False
